package com.example.automation;
import io.cucumber.java.After; import io.cucumber.java.Before; import org.openqa.selenium.WebDriver; import org.openqa.selenium.chrome.ChromeOptions; import org.openqa.selenium.chrome.ChromeDriver; import io.github.bonigarcia.wdm.WebDriverManager;
public class DriverHooks { private static final ThreadLocal<WebDriver> DRIVER=new ThreadLocal<>(); @Before public void start(){WebDriverManager.chromedriver().setup();ChromeOptions options=new ChromeOptions();if(Boolean.parseBoolean(System.getProperty("headless","true")))options.addArguments("--headless=new");options.addArguments("--no-sandbox","--disable-dev-shm-usage","--window-size=1440,1000");DRIVER.set(new ChromeDriver(options));} @After public void stop(){WebDriver d=DRIVER.get();if(d!=null){d.quit();DRIVER.remove();}} public static WebDriver driver(){return DRIVER.get();} }